            notes.append("Requires streaming features")
    sme_modes = [str(value).strip() for value in item.get("sme_modes") or [] if str(value).strip()]
    if sme_modes:
        sections["Required keyword attributes"] = "\n".join(sme_modes)
    return notes, sections

