static void prolql1(int n, std::vector<double> &d, std::vector<double> &e) {
  if (n == 1) return;

  for (int i = 1; i < n; ++i) e[i - 1] = e[i];
  e[n - 1] = 0.0;

  for (int l = 0; l < n; ++l) {
    int j = 0;
    while (true) {
      int m;
      for (m = l; m < n - 1; ++m) {
        double tst1 = std::abs(d[m]) + std::abs(d[m + 1]);
        double tst2 = tst1 + std::abs(e[m]);
        if (tst2 == tst1) break;
      }

      if (m == l) break;
      if (j == 30) throw finufft::exception(FINUFFT_ERR_PSWF_SETUP);
      ++j;

      double g = (d[l + 1] - d[l]) / (2. * e[l]);
      double r = std::sqrt(g * g + 1.0);
      g        = d[m] - d[l] + e[l] / (g + std::copysign(r, g));
      double s = 1.0;
      double c = 1.0;
      double p = 0.0;

      for (int i = m - 1; i >= l; --i) {
        double f = s * e[i];
        double b = c * e[i];
        r        = std::sqrt(f * f + g * g);
        e[i + 1] = r;
        if (r == 0.0) {
          d[i + 1] -= p;
          e[m] = 0.0;
          break;
        }
        s        = f / r;
        c        = g / r;
        g        = d[i + 1] - p;
        r        = (d[i] - g) * s + 2. * c * b;
        p        = s * r;
        d[i + 1] = g + p;
        g        = c * r - b;
      }

      if (r == 0.) break;
      d[l] -= p;
      e[l] = g;
      e[m] = 0.0;
    }

    for (int i = l; (i > 0) && (d[i] < d[i - 1]); --i) std::swap(d[i], d[i - 1]);
  }
}

