  for (long i = 0; i < n; ++i) {
    float t = x[i];
    // Newton steps instead of sqrtf: freestanding, no libm call
    float g = t * 0.5f + 0.5f;
    for (int k = 0; k < 4; ++k) g = 0.5f * (g + t / g);
