def dependents(nodes, ids):
    """Every node whose output depends on one of `ids`; reads deps only, not states."""
    seen = set(ids)
    changed = True
    while changed:
        changed = {i for i, n in nodes.items() if i not in seen and seen.intersection(n["deps"])}
        seen |= changed
    return seen

