def _expand_once(nodes, seen):
    newly = set(filter(lambda i: i not in seen and not seen.isdisjoint(nodes[i]["deps"]), nodes))
    return seen | newly, newly


def dependents(nodes, ids):
    """Every node whose output depends on one of `ids`; reads deps only, not states."""
    seen = set(ids)
    while True:
        grown, newly = _expand_once(nodes, seen)
        if not newly:
            return seen
        seen = grown

