def word_f1(hyp: str, ref: str) -> float:
    h, g = Counter(re.findall(r"[\w'-]+", hyp.lower())), Counter(re.findall(r"[\w'-]+", ref.lower()))
    match = sum((h & g).values())
    if not match:
        return 0.0
    p, r = match / sum(h.values()), match / sum(g.values())
    return 100 * 2 * p * r / (p + r)

