inline int clamp_kernel_ns(int ns, double upsampfac, int max_nspread, bool is_float) {
  const int headroom = (is_float && upsampfac < common::FLOAT_CC_UPSAMPFAC_LIMIT)
                           ? common::FLOAT_MAX_NS_CC
                           : max_nspread;
  return std::min(std::max(ns, common::MIN_NSPREAD), std::min(max_nspread, headroom));
}

