def polymul_mod(a: int, b: int) -> int:
    """Multiply polynomials a, b (bit i = coeff of x^i) modulo P(x)."""
    result = 0
    for i in range(255, -1, -1):
        result <<= 1
        if result & (1 << 256):       # x^256 term appeared -> reduce
            result ^= P_INT
        if (a >> i) & 1:
            result ^= b
    return result

int64_t dot_i32(const int32_t* __restrict a, const int32_t* __restrict b, long n) {
  int64_t acc = 0;
  MCA_BEGIN(dot_i32);
  for (long i = 0; i < n; ++i) acc += (int64_t)a[i] * b[i];
  MCA_END(dot_i32);
  return acc;
}

