int64_t dot_i32(const int32_t* __restrict a, const int32_t* __restrict b, long n) {
  MCA_BEGIN(dot_i32);
  const int64_t acc = std::inner_product(a, a + n, b, int64_t{0});
  MCA_END(dot_i32);
  return acc;
}

